sys_ws_operation.operation_script:
(function process(request, response) {
    var body = request.body.data;
    if (!body.task_id || !body.agent) {
        response.setStatus(400);
        return { error: 'task_id and agent are required' };
    }
    var gr = new GlideRecord('x_1821654_governa_run');
    gr.initialize();
    gr.setValue('agent', body.agent);
    gr.setValue('task_id', body.task_id);
    gr.setValue('task_version', body.task_version || '');
    gr.setValue('seed', body.seed || '');
    gr.setValue('harness_version', body.harness_version || '');

    if (body.eval_batch) gr.setValue('eval_batch', body.eval_batch);
    if (body.agent_version) gr.setValue('agent_version', body.agent_version);
    if (body.policy_set_hash) gr.setValue('policy_set_hash', body.policy_set_hash);

    gr.setValue('started_at', new GlideDateTime());
    var sysId = gr.insert();
    if (!sysId) { response.setStatus(500); return { error: 'insert failed' }; }
    response.setStatus(201);
    return { sys_id: sysId, number: gr.getValue('number') };
})(request, response);
